@api_method
def get_trade_days(start_date=None, end_date=None, count=None):
    """
    获取指定范围的交易日

    :param start_date: 开始日期
    :type start_date : : str

    :param end_date: 结束日期
    :type end_date : : str, 回测时为回测日期，其他为当天

    :param count: 数量, 与 start_date，end_date 二选一, 不可同时使用，
    提供的组合有：[(start_date, end_date), (start_date, count), (end_date, count)]
    与end_date搭配使用时必须大于 0. 表示取 end_date 往前的 count 个交易日，包含 end_date 当天

    :return: numpy.ndarray
    """
    if start_date and len(start_date) != 8:
        system_log.error('get_trade_days的start_date[%s]参数错误' % start_date)
        return None
    elif end_date and len(end_date) != 8:
        system_log.error('get_trade_days的end_date[%s]参数错误' % end_date)
        return None
    elif count and count <= 0:
        system_log.error('get_trade_days的count[%s]参数错误' % count)
        return None
    else:
        return Engine.instance().basic_data_handler.get_trade_days(start_date, end_date, count)
